USE [cxView];
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS_USER_ACCESS_GET @iduser varchar(36)
AS BEGIN SET NOCOUNT ON;
 IF NOT EXISTS (SELECT 1 FROM dbo.TAS006 WHERE IDUSER=LTRIM(RTRIM(@iduser))) THROW 50010,'El usuario no existe.',1;
 SELECT ISNULL(a.IDMODUSU,'') ACCESSID,m.IDMOD RESOURCEID,m.IDAPP PARENTID,m.NOMMOD NAME,m.DESCMOD DESCRIPTION,CONVERT(bit,CASE WHEN m.ESTMOD='A' AND m.SACRG=1 THEN 1 ELSE 0 END) CATALOGACTIVE,CONVERT(bit,CASE WHEN a.IDMODUSU IS NULL THEN 0 ELSE 1 END) ASSIGNED FROM dbo.TAS007 m LEFT JOIN dbo.TAS008 a ON a.IDMOD=m.IDMOD AND a.IDUSER=LTRIM(RTRIM(@iduser)) AND a.ESTMODUSU='A' AND a.SACRG=1 ORDER BY m.NOMMOD;
 SELECT ISNULL(a.IDMENUUSU,'') ACCESSID,m.IDMENU RESOURCEID,m.IDMOD PARENTID,m.NOMMENU NAME,m.DESCMENU DESCRIPTION,CONVERT(bit,CASE WHEN m.ESTMENU='A' AND m.SACRG=1 THEN 1 ELSE 0 END) CATALOGACTIVE,CONVERT(bit,CASE WHEN a.IDMENUUSU IS NULL THEN 0 ELSE 1 END) ASSIGNED FROM dbo.TAS009 m LEFT JOIN dbo.TAS010 a ON a.IDMENU=m.IDMENU AND a.IDUSER=LTRIM(RTRIM(@iduser)) AND a.ESTMENUUSU='A' AND a.SACRG=1 ORDER BY m.NOMMENU;
 SELECT ISNULL(a.IDSMUSER,'') ACCESSID,s.IDSUBMENU RESOURCEID,s.IDMENU PARENTID,s.NOMSUBMNU NAME,s.DESCSUBMNU DESCRIPTION,CONVERT(bit,CASE WHEN s.ESTSUBMNU='A' AND s.SACRG=1 THEN 1 ELSE 0 END) CATALOGACTIVE,CONVERT(bit,CASE WHEN a.IDSMUSER IS NULL THEN 0 ELSE 1 END) ASSIGNED FROM dbo.TAS011 s LEFT JOIN dbo.TAS012 a ON a.IDSUBMENU=s.IDSUBMENU AND a.IDUSER=LTRIM(RTRIM(@iduser)) AND a.ESTSMUSER='A' AND a.SACRG=1 ORDER BY s.NOMSUBMNU;
 SELECT ISNULL(a.IDOPCFORMUSU,'') ACCESSID,o.IDOPCFOMR RESOURCEID,o.IDSUBMENU PARENTID,o.NOMOPC NAME,o.DESCOPC DESCRIPTION,CONVERT(bit,CASE WHEN o.ESTOPC='A' AND o.SACRG=1 THEN 1 ELSE 0 END) CATALOGACTIVE,CONVERT(bit,CASE WHEN a.IDOPCFORMUSU IS NULL THEN 0 ELSE 1 END) ASSIGNED FROM dbo.TAS015 o LEFT JOIN dbo.TAS016 a ON a.IDOPCFOMR=o.IDOPCFOMR AND a.IDUSER=LTRIM(RTRIM(@iduser)) AND a.ESTOPC='A' AND a.SACRG=1 ORDER BY o.NOMOPC;
END;
GO
